INSERT OR IGNORE INTO case_studies (slug, title, short_title, formula_summary, client_type, client_name, category, cover_image, featured_on_home, sort_order, timeline, status, problem_heading, problem_description, solution_heading, solution_description, architecture_overview, testimonial_quote, testimonial_author, testimonial_role, testimonial_company) VALUES ('garwan-law-chamber', 'Garwan Law Chamber: Modernizing Legal Intake & Attorney Portals', 'Garwan Law Chamber Practice Portal', 'An authoritative digital legal practice portal built with React 19, TypeScript, and PostgreSQL for Garwan Law Chamber, achieving an 85% reduction in initial consultation administrative scheduling time, sub-second load times, and confidential upfront case brief management.', 'Corporate & Civil Law Practice', 'Garwan Law Chamber', 'Legal Tech', '/project-images/garwan-law-chamber.webp', 1, 2, 'Live in Production', 'Live in Production', 'Unstructured Case Inquiries & Manual Advocate Coordination', 'Garwan Law Chamber handled high-stakes civil and corporate inquiries primarily through informal messaging and walk-ins. Prospective clients lacked a unified platform to review practice credentials, verify attorney jurisdictions, and submit confidential case briefs. Administrative staff spent hours daily sorting unvetted inquiries and coordinating lawyer schedules manually.', 'Structured Case Intake & Advocate Consultation Management', 'Tech Agenz designed and engineered a bespoke, secure legal technology portal tailored to the chamber''s practice hierarchy. The platform incorporates structured case intake forms with preliminary fact gathering, automated appointment booking synced to advocate calendars, and authoritative practice directories that present credentials with institutional prestige.', 'Server-rendered architecture built with React 19, TypeScript, and PostgreSQL. Client inquiry payloads are validated, structured, and securely delivered to the chamber''s administrative portal with calendar synchronization.', 'The portal gave our law chamber a modern, authoritative digital presence. Initial consultation intake is now structured and efficient, saving our advocates valuable time.', 'Senior Advocate', 'Partner', 'Garwan Law Chamber');
