INSERT OR IGNORE INTO case_studies (slug, title, short_title, formula_summary, client_type, client_name, category, cover_image, featured_on_home, sort_order, timeline, status, problem_heading, problem_description, solution_heading, solution_description, architecture_overview, testimonial_quote, testimonial_author, testimonial_role, testimonial_company) VALUES ('dr-sajid-sohail', 'Dr. Sajid Sohail: High-Volume Clinic Operations & Patient Consultation Portal', 'Dr. Sajid Sohail Clinic Portal', 'A responsive patient booking and clinical consultation workflow system built with React 19, TypeScript, and PostgreSQL for Dr. Sajid Sohail at Rahmania Medical Center, achieving a <5% patient no-show rate, saving 4 minutes per consultation intake, and increasing monthly consultations by 35%.', 'Hospital & Medical Center Healthcare', 'Dr. Sajid Sohail (Rahmania Medical Center)', 'Healthcare', '/project-images/dr-sajid-sohail.webp', 1, 3, 'Live in Production', 'Live in Production', 'Hospital Quota Coordination & Manual Intake Bottlenecks', 'Operating within Rahmania Medical Center, Dr. Sajid Sohail required a specialized digital workflow that coordinated seamlessly between hospital reception, patient inquiries, and daily consultation quotas. Relying on paper charts and phone calls led to scheduling gaps, manual errors in patient record intake, and high no-show rates during bad weather or hospital emergencies.', 'Dynamic 15-Minute Slot Allocation & Pre-Consultation Questionnaires', 'We built a tailored medical portal with 15-minute slot allocation, intelligent patient symptom intake questionnaires, and automated clinic confirmation notifications. The system features a doctor control panel to view expected patient volumes, mark completed consultations, and seamlessly reschedule appointments with one click.', 'Lightweight, sub-second web architecture connecting patient booking with the doctor''s consultation desk and hospital reception. Intake data is cached and synchronized in real time.', 'The digital consultation workflow transformed our clinic. The 15-minute slot allocation keeps us on schedule, and pre-filled symptom questionnaires save valuable doctor time with every patient.', 'Clinical Practice Manager', 'Operations Coordinator', 'Rahmania Medical Center');
